using System.Text.Json;
using Nextended.CodeGen.Config;
using Nextended.CodeGen.Contracts;
using Nextended.Core.Enums;
using Shouldly;
using static Nextended.CodeGen.Tests.TestCompilation;

namespace Nextended.CodeGen.Tests;

/// <summary>DTO views: every [AutoGenerateDto] after the first on a type generates one more DTO of it.</summary>
[TestClass]
public class DtoViewTests
{
    private static DtoGenerationConfig Config(Action<DtoGenerationConfig>? configure = null)
    {
        var config = new DtoGenerationConfig
        {
            Namespace = "Shop.Contracts",
            OutputPath = "dtos/",
            MappingOutputPath = "mapping/",
            DeepProperties = true,
            CreateFileHeaders = false,
            CreateRegions = false,
            CreateComments = false
        };
        configure?.Invoke(config);
        return config;
    }

    private static string File(IEnumerable<GeneratedFile> files, string name) => files.Single(f => f.FileName == name).Content;

    // The default DTOs are the OData shapes; the views are the ABP shapes of the same entities.
    private const string Entities = """
        using System;
        using System.Collections.Generic;
        using Nextended.Core.Attributes;

        namespace Shop.Domain;

        [AutoGenerateDto]
        public abstract class BaseEntity
        {
            public DateTimeOffset DateCreatedUtc { get; set; }
            public DateTimeOffset DateUpdatedUtc { get; set; }
        }

        [AutoGenerateDto]
        public abstract class GuidBaseEntity : BaseEntity
        {
            public Guid Id { get; set; }
        }

        // one view for all code entities: declared on their common base
        [AutoGenerateDto(AutoGenerateDerived = true)]
        [AutoGenerateDto(GeneratedClassName = "HubCode", PropertiesToIgnore = new[] { "DateCreatedUtc", "DateUpdatedUtc", "CargonerdsCustomerId" })]
        public abstract class CodeEntity : GuidBaseEntity
        {
            public string Code { get; set; } = "";
            public string? Description { get; set; }
            public Guid? CargonerdsCustomerId { get; set; }
            public bool IsVisibleInSpark { get; set; }
        }

        public class Incoterm : CodeEntity { }

        public class Currency : CodeEntity
        {
            public int Decimals { get; set; }
        }

        // the default enum DTO is sent by name, the view by number
        [AutoGenerateDto(PreClassString = "[System.Text.Json.Serialization.JsonConverter(typeof(System.Text.Json.Serialization.JsonStringEnumConverter))]")]
        [AutoGenerateDto(GeneratedClassName = "QuotationStatusAbp")]
        public enum QuotationStatus { Draft, Requested, Quoted }

        [AutoGenerateDto]
        public class Coordinates
        {
            public double Latitude { get; set; }
            public double Longitude { get; set; }
        }

        [AutoGenerateDto(AutoGenerateDerived = true)]
        public class Country : GuidBaseEntity
        {
            public string? Name { get; set; }
        }

        // 16 members, the view keeps 8
        [AutoGenerateDto(AutoGenerateDerived = true)]
        [AutoGenerateDto(GeneratedClassName = "PortAbp", PropertiesToIgnore = new[] { "DateCreatedUtc", "DateUpdatedUtc", "Country", "IsRailTerminal", "IsRoadTerminal", "IsPostalOffice", "IsBorder", "ExternalIds" })]
        public class Port : GuidBaseEntity
        {
            public string? Name { get; set; }
            public string? IataCode { get; set; }
            public string UnLoCode { get; set; } = "";
            public string? CountryIsoAlpha2Code { get; set; }
            public Country? Country { get; set; }
            public Coordinates? Coordinates { get; set; }
            public bool IsMaritimePort { get; set; }
            public bool IsRailTerminal { get; set; }
            public bool IsRoadTerminal { get; set; }
            public bool IsAirport { get; set; }
            public bool IsPostalOffice { get; set; }
            public bool IsBorder { get; set; }
            public string? ExternalIds { get; set; }
        }

        [AutoGenerateDto(AutoGenerateDerived = true)]
        [AutoGenerateDto(GeneratedClassName = "QuotationAbp",
            PropertyNames = new[] { "DateCreatedUtc=CreationTime", "DateUpdatedUtc=LastModificationTime" },
            UseViews = new[] { "PortAbp", "HubCode", "QuotationStatusAbp" },
            PropertiesToIgnore = new[] { "InternalNote" })]
        public class Quotation : GuidBaseEntity
        {
            public string QuoteNumber { get; set; } = "";
            public QuotationStatus Status { get; set; }
            public Port? PortOriginRequested { get; set; }
            public Incoterm? IncoTerm { get; set; }
            public Currency? Currency { get; set; }
            public List<Port> Stops { get; set; } = new();
            public string? InternalNote { get; set; }
        }
        """;

    [TestMethod]
    public void A_view_is_flat_renames_inherited_members_and_uses_the_views_of_its_member_types()
    {
        var (files, diagnostics) = GenerateWithDiagnostics(CompileWithInTreeAttributes(Entities), Config());
        diagnostics.ShouldBeEmpty();

        var view = File(files, "QuotationAbpDto.g.cs");
        view.ShouldContain("public partial class QuotationAbpDto : IQuotationAbpDto"); // no base DTO
        view.ShouldContain("public System.DateTimeOffset CreationTime { get; set; }");
        view.ShouldContain("public System.DateTimeOffset LastModificationTime { get; set; }");
        view.ShouldContain("public System.Guid Id { get; set; }");
        view.ShouldNotContain("DateCreatedUtc");
        view.ShouldNotContain("InternalNote");
        view.ShouldContain("Shop.Contracts.QuotationStatusAbpDto Status");
        view.ShouldContain("Shop.Contracts.PortAbpDto? PortOriginRequested");
        view.ShouldContain("Shop.Contracts.HubCodeDto? IncoTerm");
        view.ShouldContain("Shop.Contracts.HubCodeDto? Currency");
        view.ShouldContain("System.Collections.Generic.List<Shop.Contracts.PortAbpDto> Stops");

        var port = File(files, "PortAbpDto.g.cs");
        port.Split('\n').Count(l => l.Contains("{ get; set; }") && l.TrimStart().StartsWith("public ")).ShouldBe(8);
        port.ShouldContain("Shop.Contracts.CoordinatesDto? Coordinates"); // no view listed: the default DTO

        var code = File(files, "HubCodeDto.g.cs");
        code.ShouldContain("public partial class HubCodeDto : IHubCodeDto"); // concrete, although CodeEntity is abstract
        code.ShouldNotContain("DateCreatedUtc");

        File(files, "QuotationStatusAbpDto.g.cs").ShouldNotContain("JsonConverter");
        File(files, "QuotationStatusDto.g.cs").ShouldContain("JsonStringEnumConverter");

        // the default DTOs stay as they were
        var dto = File(files, "QuotationDto.g.cs");
        dto.ShouldContain("public partial class QuotationDto :  Shop.Contracts.GuidBaseEntityDto, IQuotationDto");
        dto.ShouldContain("Shop.Contracts.PortDto? PortOriginRequested");
        dto.ShouldContain("Shop.Contracts.IncotermDto? IncoTerm");
        dto.ShouldContain("Shop.Contracts.QuotationStatusDto Status");
    }

    [TestMethod]
    public void Default_dtos_are_the_same_with_and_without_views()
    {
        var withViews = Generate(CompileWithInTreeAttributes(Entities), Config());
        var withoutViews = Generate(CompileWithInTreeAttributes(string.Join("\n", Entities.Split('\n').Where(l => !l.Contains("GeneratedClassName")
            && !l.TrimStart().StartsWith("PropertyNames") && !l.TrimStart().StartsWith("UseViews") && !l.TrimStart().StartsWith("PropertiesToIgnore = new[] { \"InternalNote\" })]")))), Config());

        withoutViews.ShouldNotBeEmpty();
        foreach (var file in withoutViews.Where(f => f.FileName != "ComGuids.g.cs"))
            File(withViews, file.FileName).ShouldBe(file.Content, file.FileName);
        withViews.Select(f => f.FileName).Except(withoutViews.Select(f => f.FileName)).OrderBy(n => n).ShouldBe(
        [
            "HubCodeDto.g.cs", "MappingExtensions.g.CodeEntity.HubCodeDto.cs", "MappingExtensions.g.Port.PortAbpDto.cs",
            "MappingExtensions.g.Quotation.QuotationAbpDto.cs", "MappingExtensions.g.QuotationStatus.QuotationStatusAbpDto.cs",
            "PortAbpDto.g.cs", "QuotationAbpDto.g.cs", "QuotationStatusAbpDto.g.cs"
        ]);
    }

    [TestMethod]
    public void Extension_mapping_maps_to_and_from_the_view()
    {
        var compilation = CompileWithInTreeAttributes(Entities);
        var files = Generate(compilation, Config());
        var mapping = File(files, "MappingExtensions.g.Quotation.QuotationAbpDto.cs");
        mapping.ShouldContain("public static Shop.Contracts.QuotationAbpDto ToQuotationAbpDto(this Shop.Domain.Quotation src)");
        mapping.ShouldContain("dest.CreationTime = src.DateCreatedUtc;");
        mapping.ShouldContain("dest.PortOriginRequested = src.PortOriginRequested?.ToPortAbpDto();");
        mapping.ShouldContain("dest.IncoTerm = src.IncoTerm?.ToHubCodeDto();");
        mapping.ShouldContain("dest.Status = src.Status.ToQuotationStatusAbpDto();");
        mapping.ShouldContain("dest.DateCreatedUtc = src.CreationTime;"); // back
        mapping.ShouldContain("// skipped 'IncoTerm': the view HubCodeDto cannot create a Incoterm");
        File(files, "MappingExtensions.g.CodeEntity.HubCodeDto.cs").ShouldNotContain("ToNet("); // CodeEntity is abstract

        var assembly = Load(CompileWithGenerated(compilation, files));
        var created = new DateTimeOffset(2026, 1, 2, 3, 4, 5, TimeSpan.Zero);
        var incoterm = New(assembly, "Shop.Domain.Incoterm", ("Code", "FOB"), ("Description", "Free on board"));
        var port = New(assembly, "Shop.Domain.Port", ("UnLoCode", "DEHAM"), ("Name", "Hamburg"), ("IsBorder", true));
        var quotation = New(assembly, "Shop.Domain.Quotation", ("QuoteNumber", "Q-1"), ("DateCreatedUtc", created), ("IncoTerm", incoterm),
            ("PortOriginRequested", port), ("Status", Enum.Parse(assembly.GetType("Shop.Domain.QuotationStatus")!, "Requested")));

        var abp = Invoke(assembly, "Shop.Contracts.MappingExtensions", "ToQuotationAbpDto", quotation);
        Get(abp, "CreationTime").ShouldBe(created);
        Get(Get(abp, "IncoTerm")!, "Code").ShouldBe("FOB");
        Get(abp, "IncoTerm")!.GetType().Name.ShouldBe("HubCodeDto");
        Get(Get(abp, "PortOriginRequested")!, "UnLoCode").ShouldBe("DEHAM");

        var json = JsonSerializer.Serialize(abp);
        json.ShouldContain("\"Status\":1");
        json.ShouldContain("\"CreationTime\":");
        json.ShouldNotContain("IsBorder");
        JsonSerializer.Serialize(Invoke(assembly, "Shop.Contracts.MappingExtensions", "ToDto", quotation)).ShouldContain("\"Status\":\"Requested\"");

        var back = Invoke(assembly, "Shop.Contracts.MappingExtensions", "ToNet", abp);
        Get(back, "DateCreatedUtc").ShouldBe(created);
        Get(Get(back, "PortOriginRequested")!, "UnLoCode").ShouldBe("DEHAM");
        Get(back, "IncoTerm").ShouldBeNull();
    }

    [TestMethod]
    public void Mapperly_mapping_of_views_compiles_without_warnings()
    {
        var compilation = CompileWithInTreeAttributes(Entities);
        var files = Generate(compilation, Config(c => c.DefaultMappingSettings = new DefaultMappingSettings
        {
            Strategy = DtoMappingStrategy.Mapperly, SkipReverseMapping = true
        }));

        var mapper = File(files, "QuotationAbpDtoMapper.g.cs");
        mapper.ShouldContain("public static partial class QuotationAbpDtoMapper");
        mapper.ShouldContain("[MapProperty(\"DateCreatedUtc\", \"CreationTime\")]");
        mapper.ShouldContain("[UseStaticMapper(typeof(Shop.Contracts.PortAbpDtoMapper))]");
        mapper.ShouldContain("[UseStaticMapper(typeof(Shop.Contracts.HubCodeDtoMapper))]");
        mapper.ShouldContain("public static partial Shop.Contracts.QuotationAbpDto ToQuotationAbpDto(this Shop.Domain.Quotation src);");
        File(files, "HubCodeDtoMapper.g.cs").ShouldContain("ToHubCodeDto(this Shop.Domain.CodeEntity src)");
        File(files, "QuotationMapper.g.cs").ShouldContain("Shop.Contracts.QuotationDto ToDto(this Shop.Domain.Quotation src)");

        var assembly = Load(CompileWithGenerated(compilation, files));
        var quotation = New(assembly, "Shop.Domain.Quotation", ("QuoteNumber", "Q-1"),
            ("Currency", New(assembly, "Shop.Domain.Currency", ("Code", "EUR"))));
        var abp = Invoke(assembly, "Shop.Contracts.QuotationAbpDtoMapper", "ToQuotationAbpDto", quotation);
        Get(Get(abp, "Currency")!, "Code").ShouldBe("EUR");
        Get(abp, "Currency")!.GetType().Name.ShouldBe("HubCodeDto");
    }

    private const string ViewSettings = """
        using System;
        using Nextended.Core.Attributes;

        namespace Shop.Domain;

        [AutoGenerateDto]
        [AutoGenerateDto(GeneratedClassName = "OrderRow", OutputPath = "rows/")]
        [AutoGenerateDto(GeneratedClassName = "OrderExport", Namespace = "Shop.Export", GenerateMapping = false)]
        public class Order
        {
            [GenerationPropertySetting(PreClassString = "[System.ComponentModel.Description(\"no\")]")]
            [GenerationPropertySetting(View = "OrderRow", PropertyName = "No")]
            public string Number { get; set; } = "";

            [IgnoreOnGeneration]
            public string Secret { get; set; } = "";
        }
        """;

    [TestMethod]
    public void A_property_setting_for_a_view_replaces_the_general_one_and_views_have_their_own_namespace_and_output_path()
    {
        var compilation = CompileWithInTreeAttributes(ViewSettings);
        var files = Generate(compilation, Config());

        var dto = files.Single(f => f.FileName == "OrderDto.g.cs");
        dto.Content.ShouldContain("[System.ComponentModel.Description(\"no\")]");
        dto.Content.ShouldContain(" Number { get; set; }");
        dto.OutputPath.ShouldBe("dtos/");

        var row = files.Single(f => f.FileName == "OrderRowDto.g.cs");
        row.Content.ShouldContain("public string No { get; set; }");
        row.Content.ShouldNotContain("Description");
        row.OutputPath.ShouldBe("rows/");

        var export = files.Single(f => f.FileName == "OrderExportDto.g.cs");
        export.Namespace.ShouldBe("Shop.Export");
        export.Content.ShouldContain("Description(\"no\")"); // the general setting
        export.Content.ShouldNotContain("Secret");
        files.ShouldNotContain(f => f.FileName.Contains("OrderExportDto.cs"));

        File(files, "MappingExtensions.g.Order.OrderRowDto.cs").ShouldContain("dest.No = src.Number;");
        CompileWithGenerated(compilation, files);
    }

    [TestMethod]
    public void Views_get_files_of_their_own_with_one_file_per_namespace()
    {
        var compilation = CompileWithInTreeAttributes(Entities);
        var files = Generate(compilation, Config(c => c.OneFilePerClass = false));
        files.ShouldContain(f => f.FileName == "QuotationAbpDto.g.cs");
        files.ShouldContain(f => f.FileName == "Shop.Contracts.AllDtos.g.cs");
        File(files, "Shop.Contracts.AllDtos.g.cs").ShouldNotContain("class QuotationAbpDto");
        CompileWithGenerated(compilation, files);
    }

    [TestMethod]
    public void Invalid_views_are_reported_and_left_out()
    {
        const string source = """
            using Nextended.Core.Attributes;

            namespace Shop.Domain;

            [AutoGenerateDto]
            [AutoGenerateDto(Suffix = "Row")]
            [AutoGenerateDto(GeneratedClassName = "Item")]
            [AutoGenerateDto(GeneratedClassName = "ItemA", ToDtoMethodName = "ToDto")]
            [AutoGenerateDto(GeneratedClassName = "ItemB", UseViews = new[] { "Nope" }, PropertyNames = new[] { "Name", "Missing=X" })]
            public class Item
            {
                public string Name { get; set; } = "";
            }

            [AutoGenerateDto]
            [AutoGenerateDto(GeneratedClassName = "ItemB")]
            public class Other
            {
                public string Name { get; set; } = "";
            }
            """;
        var compilation = CompileWithInTreeAttributes(source);
        var (files, diagnostics) = GenerateWithDiagnostics(compilation, Config());

        diagnostics.Select(d => d.Id).OrderBy(i => i).ShouldBe(["NCG010", "NCG011", "NCG011", "NCG012", "NCG013", "NCG014", "NCG014"]);
        diagnostics.Where(d => d.Id == "NCG011").Select(d => d.Severity).ShouldAllBe(s => s == Microsoft.CodeAnalysis.DiagnosticSeverity.Error);
        diagnostics.ShouldAllBe(d => d.Location.IsInSource);
        files.Select(f => f.FileName).Where(n => n.EndsWith("Dto.g.cs")).OrderBy(n => n).ShouldBe(["ItemBDto.g.cs", "ItemDto.g.cs", "OtherDto.g.cs"]);
        CompileWithGenerated(compilation, files);
    }

    [TestMethod]
    public void Mapperly_maps_views_back_except_views_of_abstract_types()
    {
        var compilation = CompileWithInTreeAttributes(Entities);
        var files = Generate(compilation, Config(c => c.DefaultMappingSettings = new DefaultMappingSettings { Strategy = DtoMappingStrategy.Mapperly }));

        var mapper = File(files, "QuotationAbpDtoMapper.g.cs");
        mapper.ShouldContain("[MapProperty(\"CreationTime\", \"DateCreatedUtc\")]");
        mapper.ShouldContain("public static partial Shop.Domain.Quotation ToNet(this Shop.Contracts.QuotationAbpDto src);");
        File(files, "HubCodeDtoMapper.g.cs").ShouldNotContain("ToNet");
        CompileWithGenerated(compilation, files);
    }

    private const string DefaultWithViews = """
        using System.Collections.Generic;
        using Nextended.Core.Attributes;

        namespace Shop.Domain;

        [AutoGenerateDto]
        [AutoGenerateDto(GeneratedClassName = "CodeRef", PropertiesToIgnore = new[] { "Description" })]
        public class Code
        {
            public string Value { get; set; } = "";
            public string? Description { get; set; }
        }

        // the default DTO can use views and rename members too; a view of the type itself stays that view
        [AutoGenerateDto(UseViews = new[] { "CodeRef" }, PropertyNames = new[] { "Label=Title" })]
        [AutoGenerateDto(GeneratedClassName = "NodeRow", UseViews = new[] { "CodeRef" })]
        public class Node
        {
            public string Label { get; set; } = "";
            public Code? Code { get; set; }
            public Node? Parent { get; set; }
            public List<Node> Children { get; set; } = new();
        }
        """;

    [TestMethod]
    public void A_default_dto_can_use_views_and_a_view_refers_to_itself()
    {
        var compilation = CompileWithInTreeAttributes(DefaultWithViews);
        var (files, diagnostics) = GenerateWithDiagnostics(compilation, Config());
        diagnostics.ShouldBeEmpty();

        var dto = File(files, "NodeDto.g.cs");
        dto.ShouldContain("public Shop.Contracts.CodeRefDto? Code { get; set; }");
        dto.ShouldContain("public string Title { get; set; }");
        dto.ShouldContain("public Shop.Contracts.NodeDto? Parent { get; set; }");

        var row = File(files, "NodeRowDto.g.cs");
        row.ShouldContain("public string Label { get; set; }"); // the rename is the default DTO's
        row.ShouldContain("public Shop.Contracts.NodeRowDto? Parent { get; set; }");
        row.ShouldContain("System.Collections.Generic.List<Shop.Contracts.NodeRowDto> Children");
        File(files, "MappingExtensions.g.Node.NodeRowDto.cs").ShouldContain("dest.Parent = src.Parent?.ToNodeRowDto();");

        var assembly = Load(CompileWithGenerated(compilation, files));
        var node = New(assembly, "Shop.Domain.Node", ("Label", "child"), ("Parent", New(assembly, "Shop.Domain.Node", ("Label", "root"))));
        var mapped = Invoke(assembly, "Shop.Contracts.MappingExtensions", "ToNodeRowDto", node);
        Get(Get(mapped, "Parent")!, "Label").ShouldBe("root");
    }
}
